SELECT TEMP.*, B.BUSI_ID AS busiId, B.INV_AIM AS invAim, ifnull(B.SEC_MANAGE_ACCT_ID,'999999') AS secManageAcctId FROM ( SELECT SUM(if(A.CD_FLAG='D',-1*A.O_HAPPEN_AMT,A.O_HAPPEN_AMT)) AS jcForO, SUM(if(A.CD_FLAG='D',-1*A.B_HAPPEN_AMT,A.B_HAPPEN_AMT)) AS jcForB, A.BOOKSET_ID AS booksetId, A.BOOK_DATE AS bookDate, A.HAPPEN_DATE AS happenDate, A.BOK_DETAIL_ID AS bokDetailId FROM BOK_BOOKDETAIL_CURRENT A WHERE A.SUBJECT_NO IN
#{item,jdbcType=VARCHAR}
AND A.TABLE_ID NOT IN ('8019','8021') GROUP BY A.BOOKSET_ID,A.BOOK_DATE,A.HAPPEN_DATE,A.BOK_DETAIL_ID ) TEMP LEFT JOIN BOK_DETAIL_ID B ON TEMP.booksetId = B.BOOKSET_ID AND TEMP.bokDetailId = B.BOK_DETAIL_ID

SELECT PRD.portfolio_id portfolioId, ifnull(PRD.channel_id,'999999') channelId, TEMP.bookset_id booksetId, TEMP.bok_detail_id bokDetailId, TEMP.BUSI_ID finprodId, TEMP.BUSI_DETAIL_TYPE finprodType, ifnull(TEMP.INV_AIM,'999999') invAim, TEMP.BRANCH branch, TEMP.O_CCY oCcy, TEMP.BAL_FLAG_HAPPEN_DATE balFlagHappenDate, TEMP.O_AMT_HAPPEN_DATE oAmtHappenDate, TEMP.BASE_SUBJECT_NATURE baseSubjectNature FROM ( SELECT bc.bookset_id, bc.bok_detail_id, bdi.BUSI_ID, bdi.BUSI_DETAIL_TYPE, bdi.INV_AIM, bc.BRANCH, bc.O_CCY, bc.BAL_FLAG_HAPPEN_DATE, bc.O_AMT_HAPPEN_DATE, bc.rn, bc.HAPPEN_DATE, bc.BASE_SUBJECT_NATURE FROM ( SELECT tmp.*, @rownum := @rownum + 1 rownum, /* 虚拟列行标 */ IF( ( @BOOKSET_ID = tmp.BOOKSET_ID and @BOK_DETAIL_ID = tmp.BOK_DETAIL_ID and @BASE_SUBJECT_NATURE = tmp.BASE_SUBJECT_NATURE and @BRANCH = tmp.BRANCH and @O_CCY = tmp.O_CCY ), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */ @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */ , @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件1 */ , @BASE_SUBJECT_NATURE := tmp.BASE_SUBJECT_NATURE /* 分组条件1 */ , @BRANCH := tmp.BRANCH /* 分组条件1 */ , @O_CCY := tmp.O_CCY /* 分组条件1 */ FROM ( /* 数据源 */ SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOK_ORDER desc ) tmp, /* 定义临时变量池 */ (SELECT @rownum := 0, @BOOKSET_ID := null, @BOK_DETAIL_ID := null, @BASE_SUBJECT_NATURE := null, @BRANCH := null, @O_CCY := null, @rank := 0) a ) bc LEFT JOIN BOK_DETAIL_ID bdi ON bdi.bookset_id = bc.bookset_id AND bdi.bok_detail_id = bc.bok_detail_id WHERE bc.BASE_SUBJECT_NATURE IN ('QTYSK_BJ','QTYSK_LX') AND bc.HAPPEN_DATE <= #{happenDate,jdbcType=DATE} AND bc.BOOK_DATE <= #{happenDate,jdbcType=DATE} AND (bc.OFFSET_DATE < #{happenDate,jdbcType=DATE} OR bc.OFFSET_DATE IS NULL) ) TEMP LEFT JOIN ( select b.bookset_id,
case when c.channel_id is null then case when b.acct_mode = '02' then b.acct_subject_id else ifnull(d.portfolio_id,b.acct_subject_id) end else case when e.acct_mode='02' then e.acct_subject_id else ifnull(f.portfolio_id,e.acct_subject_id) end end portfolio_id, c.channel_id, ifnull(c.bookset_id,b.bookset_id) f_bookset_id from bok_bookset b left join bok_bookset_re c on b.bookset_id = c.bookset_id_son left join fin_product_add d on b.acct_subject_id = d.finprod_id left join bok_bookset e on c.bookset_id = e.bookset_id left join fin_product_add f on e.acct_subject_id = f.finprod_id WHERE B.START_DATE <= #{happenDate,jdbcType=DATE} AND B.END_DATE > #{happenDate,jdbcType=DATE} ) PRD ON TEMP.bookset_id = PRD.bookset_id WHERE TEMP.rn = 1 AND TEMP.O_AMT_HAPPEN_DATE >= 0
AND (PRD.f_bookset_id in
null) OR PRD.f_bookset_id in (
#{item}
)

